; dados.asm
.data

    ; Cores VGA
    C equ 0Ch ;vermelho claro
    E equ 0Eh ;amarelo
    A equ 0Ah ;verde claro
    D equ 0Dh ;magenta claro
    B equ 0Bh ;ciano claro
    
    ; Constantes 
    CR equ 13
    NL equ 10 
    TAM_SPRITE EQU 29*13
    
    ; ============= MENU =============
    ; Titulo do jogo
            
    msg      db "     ____                   __   __   " , CR, NL
             db "    / __/__________ ___ _  / /  / /__ " , CR, NL
             db "   _\ \/ __/ __/ _ `/  ' \/ _ \/ / -_)" , CR, NL
             db "  /___/\__/_/  \_,_/_/_/_/_.__/_/\__/ " 
                                               
            
             TAM_MSG equ $-msg 
    
    ; Autores do jogo
    nomes    db 'Cristersom Simionato e Wellinton Sartori', CR, NL
    TAM_NOMES equ $-nomes 
    
    ; Strings do menu
    menu_jogar_des db '                Jogar  '          ; Texto do bot?o "Jogar" (n?o selecionado)
    TAM_JOGAR_DES  equ $-menu_jogar_des
    menu_jogar_sel db '              [ Jogar ]'          ; Texto do bot?o "Jogar" (selecionado)
    TAM_JOGAR_SEL  equ $-menu_jogar_sel
    menu_sair_des  db '                Sair   '          ; Texto do bot?o "Sair" (n?o selecionado)
    TAM_SAIR_DES   equ $-menu_sair_des
    menu_sair_sel db '              [ Sair ] '           ; Texto do bot?o "Sair" (selecionado)
    TAM_SAIR_SEL   equ $-menu_sair_sel

    ; Controle do menu
    menu_selecionado db 0 ; 0 = Jogar, 1 = Sair
        
    ; Coordenadas da nave aliada 
    nave_aliada_x dw 10 
    nave_aliada_y dw 50 
   
    ; Coordenadas dos inimigos
    nave_alien_x dw 120 
    nave_alien_y dw 120
    meteoro_x dw 110    
    meteoro_y dw 90   
  
    ; Direcao no qual as naves est?o indo (1 direita) 
    direcao_atual dw 1
    direcao_atual2 dw 1  
    direcao_aliada_y db 1
    
    ; Delay do menu
    delay_cx dw 0
    delay_dx dw 50000 
    
    ; ============= HUD =============
    ; Campos numericos da hud
    campo3     db '00000'
    TAM_MSG5 equ 5
    campo4     db '60'
    TAM_MSG6 equ 2
    campo1     db 'SCORE:'
    TAM_MSG3 equ $-campo1 
    campo2     db 'TEMPO:'
    TAM_MSG4 equ $-campo2 
    
    ; Variaveis para o tempo
    tempo_restante  db 60        ; Tempo das fases
    timer_counter   db 38        ; Quantidade de iteracoes para contar 1 unidade de tempo
    
    ; Variavel que informa a quantidade de vidas atual do jogador
    qtd_vidas db 3

;============= JOGO =============
    ; Variavel para saber a fase
    fase_atual dw 1
    
    ; Delay do jogo
    game_delay_cx = 0
    game_delay_dx dw 3000
    
    ; Representa o padrao de spawn que a fase tera
    random_seed dw 32141
    
    ; Informa se o player colidiu ou nao com o cenario
    COLISAO db 0
    
    ; Variaveis que indicam a situacao atual do jogador no jogo
    player_morto db 0
    player_venceu db 0
    
    ; Variavel para saber qual o tipo de rastro deixado pela nave aliada 
    rastro dw 0 
    
    ; Responsavel pelo deslocamento da superficie
    desloc_superficie dw 0
    
    ; Variaveis do tiro
    tiro_ativo db 0 
    tiro_x dw 0
    tiro_y dw 0
  
    ; Limite da tela para o jogador
    MIN_X dw 0
    MAX_X dw 292
    MIN_Y dw 10  
    MAX_Y dw 180 
    
    ; ============= FASE 1 =============
    
    ; Coordenadas para a nave do jogador 
    player_x dw 10  
    player_y dw 90  

    ; Coordenadas para os inimigos
    enemy1_x dw 90  
    enemy1_y dw 20
    enemy2_x dw 190 
    enemy2_y dw 60
    enemy3_x dw 290 
    enemy3_y dw 100

    ; ============= SPRITES DE TEXTO =============
  
    msg_fase1    db "   _______   ________  ___", CR, NL
                 db "  / __/ _ | / __/ __/ <  /", CR, NL
                 db " / _// __ |_\ \/ _/   / / ", CR, NL
                 db "/_/ /_/ |_/___/___/  /_/  ", CR, NL, 0             
                 
    msg_fase2    db "   _______   ________  ___ ", CR, NL
                 db "  / __/ _ | / __/ __/ |_  |", CR, NL
                 db " / _// __ |_\ \/ _/  / __/ ", CR, NL
                 db "/_/ /_/ |_/___/___/ /____/ ", CR, NL, 0
                 
    msg_fase3    db "   _______   ________  ____", CR, NL
                 db "  / __/ _ | / __/ __/ |_  /", CR, NL
                 db " / _// __ |_\ \/ _/  _/_ < ", CR, NL
                 db "/_/ /_/ |_/___/___/ /____/ ", CR, NL, 0   
     
    msg_game_over    db   "  ___ _ ___ _ __ _  ___    ",CR, NL
                     db   " / _ `// _ `//  ' \/ -_)   ",CR, NL
                     db   " \_, / \_,_//_/_/_/\__/    ",CR, NL
                     db   "/___/  ___  _  __ ___  ____",CR, NL
                     db   "      / _ \| |/ // -_)/ __/",CR, NL
                     db   "      \___/|___/ \__//_/   ", CR, NL, 0
                                                                                                                    
    msg_vencedor   db   "  _      _______  ___  _________  ",CR, NL
                   db   " | | /| / /  _/ |/ / |/ / __/ _ \ ",CR, NL
                   db   " | |/ |/ // //    /    / _// , _/ ",CR, NL
                   db   " |__/|__/___/_/|_/_/|_/___/_/|_|  ", CR, NL, 0                             
        
; ============= SPRITES =============
;Sprite que sera substituida pelo inimigo atual da fase
    nave_atual db (13*29) dup(?)

; Sprites vazias para apagar os rastros (sprites pretas)
    sprite_vazio db (13*29) dup(0)
    sprite_coluna_vazia db 13 DUP(0)
    sprite_linha_vazia db 29 DUP(0)
    sprite_vida_vazia db (7*19) dup(0)
    
